    internal static int RtSeg(emon.Port.Cells lines, emon.Port.Cells words, int x0, int x1, int y0, int y1, int tstart) {
        // One detector segment as the pipeline holds it after emission: a line of one word with the same box, whose text starts at `tstart`.
        int first = Evidence.WdCount(words);
        int l = Evidence.LnCount(lines);
        Evidence.WdNew(words, 1, x0, y0, x1, y1, x0, y1, x1, y1, 0, 0, tstart, 3, l, 900, -1);
        Evidence.WdSet(words, first, Evidence.WfSize(), 1200);
        Evidence.WdSet(words, first, Evidence.WfGap(), -1);
        Evidence.WdSet(words, first, Evidence.WfWbreak(), Evidence.WbLineEnd());
        Evidence.WdSet(words, first, Evidence.WfSrc(), Model.SrOcr());
        Evidence.LnNew(lines, 1, x0, y0, x1, y1, x0, y1, x1, y1, 0, 0, first, 1);
        Evidence.LnSet(lines, l, Evidence.LfSrc(), Model.SrOcr());
        Evidence.LnSet(lines, l, Evidence.LfOrder(), l);
        return l;
    }
    internal static int RtRule(emon.Port.Cells rules, int x, int y0, int y1) {
        // A vertical rule of page 1 at x from y0 to y1, 10 centipoints thick (the tracer's, as `emon.scantest` makes one).
        int r = Evidence.RlNew(rules, 1, x - 5, y0, x + 5, y1, 0);
        Evidence.RlSet(rules, r, Evidence.RlfLx0(), x);
        Evidence.RlSet(rules, r, Evidence.RlfLy0(), y0);
        Evidence.RlSet(rules, r, Evidence.RlfLx1(), x);
        Evidence.RlSet(rules, r, Evidence.RlfLy1(), y1);
        Evidence.RlSet(rules, r, Evidence.RlfThick(), 10);
        return r;
    }
    internal static int RtRuns(emon.Port.Cells runs, int granularity) {
