        int r = Evidence.OrNew(runs, 1, 0);
        Evidence.OrSet(runs, r, Evidence.OrfFlags(), 256 * granularity);
        return r;
    }
    internal static int RtRun(emon.Port.Cells lines, emon.Port.Cells words, emon.Port.Cells runs, emon.Port.Cells rules, int n) {
